import{_ as e,o,c as t,a3 as l}from"./chunks/framework.DMtjdCb-.js";const p=JSON.parse('{"title":"10. 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/troubleshooting.md","filePath":"zh-Hans/troubleshooting.md"}'),i={name:"zh-Hans/troubleshooting.md"};function r(n,a,h,d,s,c){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="_10-常见问题" tabindex="-1">10. 常见问题 <a class="header-anchor" href="#_10-常见问题" aria-label="Permalink to &quot;10. 常见问题&quot;">​</a></h1><p>从当前看到的现象开始检查。完成一项后重新尝试原来的操作，避免同时更改多项设置。</p><h2 id="open-page" tabindex="-1">页面打不开 <a class="header-anchor" href="#open-page" aria-label="Permalink to &quot;页面打不开 {#open-page}&quot;">​</a></h2><ol><li>电脑部署确认启动窗口仍在运行；Docker 查看 AnimeMachine 容器是否运行。</li><li>使用实际启动日志中的地址和端口。</li><li>从手机访问时，将 <code>localhost</code> 换成运行设备的局域网地址。</li><li>端口被其它程序占用时，按<a href="./docker.html">部署说明</a>选择空闲端口并重新启动。</li></ol><h2 id="不知道登录密码" tabindex="-1">不知道登录密码 <a class="header-anchor" href="#不知道登录密码" aria-label="Permalink to &quot;不知道登录密码&quot;">​</a></h2><p>查看首次启动窗口或容器日志。电脑发布包的初始账户在 <code>data/state/auth/initial-admin.txt</code>；Docker 默认组合在项目的 <code>data/state/auth/initial-admin.txt</code>。已经自行改过密码时，以修改后的账户为准；可让其它管理员协助管理账户。</p><h2 id="作品或图片还没有出现" tabindex="-1">作品或图片还没有出现 <a class="header-anchor" href="#作品或图片还没有出现" aria-label="Permalink to &quot;作品或图片还没有出现&quot;">​</a></h2><p>首次启动先准备近期作品，其余作品和图片随后在后台补齐。查看首页进度和 <strong>设置 → 诊断</strong> 中的网络状态；恢复连接后会继续尝试。需要查找历史作品时，可等完整资料准备完成后重新搜索。</p><h2 id="download" tabindex="-1">资源找到但没有下载 <a class="header-anchor" href="#download" aria-label="Permalink to &quot;资源找到但没有下载 {#download}&quot;">​</a></h2><ol><li>检查是否已经选择资源并确认订阅或下载计划。</li><li>在 <strong>设置 → 连接</strong> 确认 Ani-RSS / qBittorrent 可用。</li><li>在下载器查看是否已有任务、目标目录是否可用，以及是否有可连接的做种者。</li><li>Torrent 结果默认折叠时，展开对应区域再选择字幕组和版本。</li></ol><h2 id="硬盘有文件-作品却不能播放" tabindex="-1">硬盘有文件，作品却不能播放 <a class="header-anchor" href="#硬盘有文件-作品却不能播放" aria-label="Permalink to &quot;硬盘有文件，作品却不能播放&quot;">​</a></h2><ol><li>在 <strong>设置 → 连接</strong> 核对媒体目录可读。</li><li>Docker 中先核对 NAS 目录已挂载，再填写对应容器路径。</li><li>等待文件清点完成；有多个来源时切换到实际包含媒体的来源。</li><li>检查文件是否为正片、文件名是否能识别作品和集数，必要时查看<a href="./collections.html">已有收藏</a>。</li></ol><h2 id="播放器没有打开或提示地址错误" tabindex="-1">播放器没有打开或提示地址错误 <a class="header-anchor" href="#播放器没有打开或提示地址错误" aria-label="Permalink to &quot;播放器没有打开或提示地址错误&quot;">​</a></h2><ol><li>在当前设备安装播放器，并允许浏览器打开外部应用。</li><li>复制播放列表地址，在播放器中打开；也可尝试下载列表。</li><li>使用播放器所在设备可以访问的 AnimeMachine 地址，避免从其它设备使用 <code>localhost</code>。</li><li>列表已过期或作品有新集时，返回页面重新生成。</li></ol><p>Windows 安装 PotPlayer 扩展后可以记录精确位置；VLC 等方式根据媒体访问记录集数，误判时按<a href="./continue-watching.html#correct">观看记录</a>纠正。</p><h2 id="本周列表为空" tabindex="-1">本周列表为空 <a class="header-anchor" href="#本周列表为空" aria-label="Permalink to &quot;本周列表为空&quot;">​</a></h2><p>确认所选季度内有已订阅 TV 动画，并且最新一集仍待看完、已经存在可播放媒体。暂停、未订阅、隐藏及最新集已看完的作品不会进入新列表。</p><h2 id="日志中哪些内容需要处理" tabindex="-1">日志中哪些内容需要处理 <a class="header-anchor" href="#日志中哪些内容需要处理" aria-label="Permalink to &quot;日志中哪些内容需要处理&quot;">​</a></h2><p>在 <strong>设置 → 日志</strong> 选择警告与错误，结合当前操作查看最近记录。长时间无法恢复时，记录软件版本、部署方式、复现步骤与相关错误；分享截图或日志前移除密码、密钥和个人路径。</p>',19)])])}const m=e(i,[["render",r]]);export{p as __pageData,m as default};
